-- Sandbox-only mock. No network access is performed by this function.
CREATE SCHEMA IF NOT EXISTS net;
CREATE TABLE net.http_request_queue (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  method text NOT NULL,
  url text NOT NULL,
  headers jsonb NOT NULL,
  body jsonb NOT NULL,
  timeout_milliseconds integer NOT NULL
);
CREATE TABLE net._http_response (
  id bigint,
  status_code integer,
  content_type text,
  headers jsonb,
  content text,
  timed_out boolean,
  error_msg text,
  created timestamptz NOT NULL DEFAULT now()
);
CREATE FUNCTION net.http_post(
  url text,
  body jsonb DEFAULT '{}'::jsonb,
  params jsonb DEFAULT '{}'::jsonb,
  headers jsonb DEFAULT '{"Content-Type":"application/json"}'::jsonb,
  timeout_milliseconds integer DEFAULT 2000
)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'net'
AS $function$
DECLARE v_id bigint;
BEGIN
  INSERT INTO net.http_request_queue(method, url, headers, body, timeout_milliseconds)
  VALUES ('POST', url, headers, body, timeout_milliseconds)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$;
GRANT USAGE ON SCHEMA net TO PUBLIC;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA net TO PUBLIC;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA net TO PUBLIC;
